{
  "probability": 0.71,
  "range_low": 0.60,
  "range_high": 0.82,
  "summary": [
    "Posterior probability of a party or coalition winning 134+ seats in the 2026 Hungarian elections is 0.71.",
    "Forecasts are mixed: some polls hint at TISZA-led opposition, others suggest Fidesz-led outcomes or different seat distributions.",
    "The estimate reflects a calibrated Bayesian update from the historical base rate of two-thirds majorities and current polling/seat-model signals, with substantial uncertainty."
  ],
  "confidence": "medium",
  "narrative": "Starting from the historical base rate of two-thirds majorities, we updated for current polls, seat projections, and turnout dynamics. The 71% posterior reflects mixed evidence and structural uncertainty, yielding a calibrated, moderately uncertain forecast.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical frequency of two-thirds (134+) majorities in the 199-seat Hungarian National Assembly since 1990 (roughly 4 of 9 elections), used as the reference class anchor."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around the TISZA platform",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Polls showing TISZA ahead or threatening Fidesz suggest that a united opposition could translate into more seats and raise the odds of reaching 134+."
      },
      {
        "factor": "Poll heterogeneity and cross-pollster divergence",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent results across firms reduce confidence in a single outcome and dampen clear expectations about a 2/3 majority."
      },
      {
        "factor": "Electoral system effects and seat allocation bias against 2/3",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Seat projections show Fidesz not easily reaching 134+ seats under current distribution, signaling structural hurdles."
      },
      {
        "factor": "Potential influx of new entrants (e.g., Our Homeland) altering seat distribution",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Additional parties entering Parliament could shift vote shares and seat tallies in ways favorable to or against a 2/3 outcome."
      },
      {
        "factor": "Turnout dynamics favoring opposition blocs",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher turnout among opposition-leaning voters could lift opposition seats and improve probability of 134+."
      }
    ],
    "synthesis_rationale": "Starting with a 0.44 anchor, each factor updated the probability in the direction indicated, with polarizing signals (opposition momentum) and damping structural biases (electoral system) roughly offsetting each other. The resulting posterior of 0.71 reflects net upward movement from moderate to strong positives on balance, while acknowledging substantial cross-pollster uncertainty and potential turnout volatility; calibration remains moderate."
  }
}

